387, 465], \"page_id\": 9}], \"content\": \"Treasury financing operations II\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [192, 487, 1378, 547], \"page_id\": 9}], \"content\": \"Federal fiscal operations 1\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [196, 562, 1373, 620], \"page_id\": 9}], \"content\": \"Federal obligations 12\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 644, 1380, 689], \"page_id\": 9}], \"content\": \"Account of the Treasurer of the United States. 16\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [190, 721, 1378, 767], \"page_id\": 9}], \"content\": \"Monetary statistics 19\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [192, 798, 1382, 841], \"page_id\": 9}], \"content\": \"Federal debt 20\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 863, 1376, 916], \"page_id\": 9}], \"content\": \"Public debt operations 28\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 938, 1380, 991], \"page_id\": 9}], \"content\": \"United States savings bonds 64\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1015, 1376, 1066], \"page_id\": 9}], \"content\": \"United States savings notes 68\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1090, 1378, 1138], \"page_id\": 9}], \"content\": \"Ownership of Federal securities 69\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1164, 1378, 1217], \"page_id\": 9}], \"content\": \"Treasury survey of ownership 71\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1242, 1378, 1287], \"page_id\": 9}], \"content\": \"Market quotations on Treasury securities 77\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1314, 1378, 1364], \"page_id\": 9}], \"content\": \"Average yields of long-term bonds 80\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [192, 1393, 1382, 1444], \"page_id\": 9}], \"content\": \"Exchange Stabilization Fund\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1468, 1382, 1519], \"page_id\": 9}], \"content\": \"International financial statistics 84\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [187, 1545, 1371, 1596], \"page_id\": 9}], \"content\": \"Capital movements 89\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1608, 1367, 1668], \"page_id\": 9}], \"content\": \"Corporations and other business-type activities 126\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1690, 1376, 1741], \"page_id\": 9}], \"content\": \"Cumulative table of contents 127\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1806, 1063, 1849], \"page_id\": 9}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 21, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [71, 29, 96, 55], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1323, 12, 1588, 58], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [604, 293, 1080, 324], \"page_id\": 10}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 406, 279, 430], \"page_id\": 10}], \"content\": \"October Refunding\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 454, 809, 632], \"page_id\": 10}], \"content\": \"On September 17 the Treasury announced an exchange offering of 8% Treasury Notes of Series E-1971, dated October 1, 1969, due May 15, 1971, at par, 7-3/4% Treasury Notes of Series A-1973, dated October 1, 1969, due May 15, 1973, at par, and 7-1/2% Treasury Notes of Series C-1976, dated October 1, 1969,\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [880, 401, 1598, 540], \"page_id\": 10}], \"content\": \"due August 15, 1976, at 99.50 to yield about 7.99%, to hold of 1-1/2% Treasury Notes of Series EO-1969, due October 1 1969, 4% Treasury Bonds of 1969, due October 1, 1969, and 2-1/2% Treasury Bonds of 1964-69, due December 15, 1969.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [884, 564, 1598, 627], \"page_id\": 10}], \"content\": \"The following table contains figures relating to amount exchanged.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [657, 677, 1011, 704], \"page_id\": 10}], \"content\": \"(Dollar amounts in millions)\", \"description\": null, \"id\": 7, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [55, 704, 1600, 1146], \"page_id\": 10}], \"content\": \"<table><tr><th colspan=\\\"2\\\">ELIGIBLE FOR EXCHANGE</th><th colspan=\\\"4\\\">SECURITIES TO BE ISSUED</th><th colspan=\\\"2\\\">UNEXCHANGED</th></tr><tr><th>Securities</th><th>Amount</th><th>8% Notes E-1971</th><th>7-3/4% Notes A-1973</th><th>7-1/2% Notes C-1976</th><th>Total</th><th>Amount</th><th>Percent</th></tr><tr><td>1-1/2% notes</td><td>$ 159</td><td>$ 51</td><td>$ 13</td><td>$ 2</td><td>$ 66</td><td>$ 93</td><td>58.5</td></tr><tr><td>4% bonds</td><td>6,240</td><td>3,172</td><td>870</td><td>1,108</td><td>5,150</td><td>1,090</td><td>19.8</td></tr><tr><td>2-1/2% bonds</td><td>2,484</td><td>950</td><td>275</td><td>571</td><td>1,796</td><td>688</td><td>34.2</td></tr><tr><td>Total</td><td>$8,883</td><td>$4,173</td><td>$1,158</td><td>$1,681</td><td>$7,012</td><td>$1,871</td><td>24.3</td></tr></table>\", \"description\": null, \"id\": 8, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [68, 1172, 812, 1242], \"page_id\": 10}], \"content\": \"The subscription books were open from September 22 through September 24. Cash subscriptions were not accepted.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [127, 1256, 807, 1283], \"page_id\": 10}], \"content\": \"In the case of exchanges of the 2-1/2% bonds, coupons\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [873, 1172, 1596, 1271], \"page_id\": 10}], \"content\": \"dated December 15, 1969, were to be attached to the bonds and interest was to be adjusted as of that date, with payments as follows (per $1,000 face value):\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [64, 1304, 1600, 1662], \"page_id\": 10}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">NEW NOTES</th><th colspan=\\\"2\\\">Payable to Subscriber</th><th colspan=\\\"2\\\">Accrued Interest Payable</th><th colspan=\\\"2\\\">Net Amount to be Paid</th></tr><tr><th>Account of Issue Price of New Notes</th><th>To Adjust for Market Value of Bonds</th><th>To Subscriber on Bonds (6/15/69 to 12/15/69)</th><th>By Subscriber on Notes (10/1/69 to 12/15/69)</th><th>To Subscriber</th><th>To Treasury</th></tr><tr><td>8% due 5/15/71</td><td>$ -</td><td>$ 2.70</td><td>$12.50</td><td>$16.41244</td><td>$ -</td><td>$1.21244</td></tr><tr><td>7-3/4% due 5/15/73</td><td>-</td><td>2.35</td><td>12.50</td><td>15.89955</td><td>-</td><td>1.04955</td></tr><tr><td>7-1/2% due 8/15/76</td><td>5.00</td><td>2.20</td><td>12.50</td><td>15.28533</td><td>4.41467</td><td>-</td></tr></table>\", \"description\": null, \"id\": 12, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [68, 1693, 812, 1902], \"page_id\": 10}], \"content\": \"Coupons dated October 1, 1969, were to be detached from the securities maturing on that date. The October 1, 1969, interest due on registered securities maturing on that date was paid by issue of interest checks in regular course to holders of record on August 29, 1969, the date the transfer books closed.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 1931, 800, 1953], \"page_id\": 10}], \"content\": \"Interest on the 8% notes will be payable on May 15 and\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [879, 1696, 1598, 1941], \"page_id\": 10}], \"content\": \"November 15, 1970, and May 15, 1971. Interest on the 7-3/4% notes will be payable on May 15 and November 15, 1970, and thereafter on May 15 and November 15 until maturity. Interest on the 7-1/2% notes will be payable on February 15 and August 15 until maturity. The notes were issued in bearer and registered form in denominations of $1,000, $5,000, $10,000, $100,000, $1,000,000, $100,000,000, and $500,000,000.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [13, 12, 260, 55], \"page_id\": 11}], \"content\": \"October 1969\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1484, 22, 1534, 63], \"page_id\": 11}], \"content\": \"III\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [373, 272, 1182, 316], \"page_id\": 11}], \"content\": \"Treasury Financing Operations - (Continued)\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [7, 448, 284, 480], \"page_id\": 11}], \"content\": \"Tax Anticipation Bills\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [5, 497, 760, 680], \"page_id\": 11}], \"content\": \"On October 2 tenders were invited for $2.0 billion, or thereabouts, of 190-day tax anticipation bills, to be dated October 14, 1969, to mature April 22, 1970. They will be acceptable at face value in payment of income taxes due on April 15, 1970.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [5, 697, 756, 875], \"page_id\": 11}], \"content\": \"Tenders were opened on October 8 and totaled $3,179 million, of which $2,006 million was accepted. The average bank discount rate was 7.284 percent. The limit for noncompetitive tenders from any one bidder was $400,000 and they totaled $109 million.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [5, 897, 756, 1080], \"page_id\": 11}], \"content\": \"All bidders were required to agree not to purchase or to sell, or to make any agreements with respect to the purchase or sale or other disposition of any bills of the issue at a specific rate or price, until after one-thirty p.m., Eastern daylight saving time, October 8, 1969.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [7, 1097, 752, 1251], \"page_id\": 11}], \"content\": \"Any qualified depositary was permitted to make settlement by credit in its Treasury tax and loan account for not more than 50 percent of the amount of bills allotted to it for it-self and its customers.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [11, 1316, 337, 1345], \"page_id\": 11}], \"content\": \"9-Month and One-year Bills\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [11, 1360, 761, 1656], \"page_id\": 11}], \"content\": \"On September 17 tenders were invited for $500 million, or thereabouts, of 273-day Treasury bills, representing an additional amount of bills dated June 30, 1969, maturing June 30, 1970, and for $1.0 billion, or thereabouts, of 365-day Treasury bills to be dated September 30, 1969, to mature September 30, 1970, both series to be issued September 30. These issues were to refund $1,501 million of bills maturing September 30. Tenders were opened on September 23.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [15, 1673, 765, 1818], \"page_id\": 11}], \"content\": \"Tenders received for the 273-day bills totaled $1,258 million, of which $500 million was accepted, including $16 million of noncompetitive tenders. The average bank discount rate was 7.357 percent.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [11, 1839, 761, 1979], \"page_id\": 11}], \"content\": \"Tenders received for the 365-day bills totaled $1,950 million, of which $1,005 million was accepted, including $57 million of noncompetitive tenders. The average bank discount rate was 7.350 percent.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [798, 448, 1109, 482], \"page_id\": 11}], \"content\": \"13-Week and 26-Week Bills\", \"description\": null, \"id\": 12, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [800, 501, 1548, 716], \"page_id\": 11}], \"content\": \"Issues on regular weekly Treasury bills in September totaled $11.6 billion, replacing an equal amount of maturing bills. There were two 91-day issues of $1.6 billion, one 91-day issue of $1.8 billion, one 92-day issue of $1.8 billion, and four 182-day issues of $1.2 billion. Average rates for the new issues are shown in the following table.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [811, 716, 1558, 1222], \"page_id\": 11}], \"content\": \"<table><tr><th colspan=\\\"3\\\">13-week (Additional amount of bills of original maturity of 26 weeks)</th><th colspan=\\\"2\\\">26-week</th></tr><tr><th colspan=\\\"2\\\">Date of --</th><th>Approximate equivalent annual average rate 1/</th><th>Date of issue</th><th>Approximate equivalent annual average rate 1/</th></tr><tr><th>Additional issue</th><th>Original issue</th><th></th><th></th><th></th></tr><tr><td>1969</td><td>1969</td><td></td><td>1969</td><td></td></tr><tr><td>June 4</td><td>June 5</td><td>7.012</td><td>Sept. 4</td><td>7.167</td></tr><tr><td>11</td><td>12</td><td>7.183</td><td>11</td><td>7.407</td></tr><tr><td>18</td><td>19</td><td>7.156</td><td>18</td><td>7.329</td></tr><tr><td>25</td><td>26</td><td>7.162</td><td>25</td><td>7.361</td></tr></table>\", \"description\": null, \"id\": 14, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [813, 1222, 1118, 1249], \"page_id\": 11}], \"content\": \"1/ Bank discount basis.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [800, 1275, 1100, 1302], \"page_id\": 11}], \"content\": \"Treasury Bills - General\", \"description\": null, \"id\": 16, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [802, 1326, 1538, 1538], \"page_id\": 11}], \"content\": \"Treasury bills are sold on a bid basis. The face amount is payable without interest at maturity. They are issued in bearer form only, and in denominations of $1,000, $5,000, $10,000, $50,000, $100,000, $500,000, and $1,000,000 (maturity value). Tenders are received at Federal Reserve banks and branches.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [804, 1560, 1538, 1847], \"page_id\": 11}], \"content\": \"Banking institutions generally may submit tenders for account of customers. Tenders may be made without deposit by incorporated banks and trust companies and by responsible and recognized dealers in investment securities. Tenders from others must be accompanied by payment of 2 percent of the face amount of bills applied for, unless the tenders are accompanied by an express guaranty of payment by an incorporated bank or trust company.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [800, 1873, 1538, 1977], \"page_id\": 11}], \"content\": \"Noncompetitive tenders (without stated price), usually for $200,000 or less from any one bidder, are accepted in full at the average price of accepted competitive bids for an issue.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [69, 17, 118, 56], \"page_id\": 12}], \"content\": \"IV\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1318, 12, 1593, 66], \"page_id\": 12}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [486, 282, 1193, 323], \"page_id\": 12}], \"content\": \"Treasury Financing Operations - (Continued)\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [62, 444, 805, 673], \"page_id\": 12}], \"content\": \"Payment for accepted tenders must be made or completed on the date of issue, in cash or other immediately available funds or in a like face amount of Treasury bills maturing on that date. Payment for 13-week, 26-week, 9-month, and one-year bills may not be made by credit in Treasury tax and loan accounts.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [56, 678, 566, 716], \"page_id\": 12}], \"content\": \"Foreign Series and Foreign Currency Series\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [56, 731, 821, 845], \"page_id\": 12}], \"content\": \"Foreign series securities issued in September totaled $795 million, consisting of thirty-five certificates of indebtedness and two notes. Redemptions for the month totaled $855 million.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [843, 444, 1593, 525], \"page_id\": 12}], \"content\": \"At the end of September foreign series securities outstanding totaled $1,568 million. (Details are shown on pages 60-61.)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [837, 537, 1602, 848], \"page_id\": 12}], \"content\": \"Foreign currency series securities issued in September consisted of one note denominated in Swiss francs equivalent to $30 million. Redemptions for the month totaled an equivalent of $30 million. At the end of September foreign currency series securities outstanding totaled an equivalent of $2,220 million, and were denominated in Austrian schillings, German marks, Italian lire, and Swiss francs. (Details are shown on page 63.)\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [69, 1999, 1450, 2033], \"page_id\": 12}], \"content\": \"Note: Details of Treasury market financing operations are shown elsewhere in tables on public debt operations.\", \"description\": null, \"id\": 8, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [15, 12, 267, 58], \"page_id\": 13}], \"content\": \"October 1969\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1532, 51, 1548, 72], \"page_id\": 13}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [573, 77, 1001, 108], \"page_id\": 13}], \"content\": \"FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [505, 135, 1058, 166], \"page_id\": 13}], \"content\": \"Table FFO-1. - Summary of Fiscal Operations\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [653, 212, 893, 243], \"page_id\": 13}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [-5, 243, 1559, 1037], \"page_id\": 13}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Fiscal year or month</th><th colspan=\\\"6\\\">Budget receipts, expenditures, and lending</th><th colspan=\\\"5\\\">Means of financing - net transactions</th></tr><tr><th colspan=\\\"3\\\">The expenditure account</th><th colspan=\\\"3\\\">Loan account 1/</th><th colspan=\\\"5\\\">Borrowings from the public - Federal securities</th></tr><tr><th>Net receipts 2/</th><th>Net expenditures 2/</th><th>Surplus or deficit(-) (1)-(2)</th><th>Loan disbursements</th><th>Loan repayments</th><th>Net lending 2/ - (4)+(5)</th><th>Budget surplus or deficit (-) (3)+(6)</th><th>Public debt securities</th><th>Agency securities</th><th>Investments of Government acc