 {\"bbox\": [{\"coord\": [56, 590, 787, 801], \"page_id\": 28}], \"content\": \"Deposits to tax and loan accounts occur in the normal course of business under a uniform procedure applicable to all banks whereby customers of banks deposit with them payments and funds for the purchase of Government securities. In most cases the transaction involves merely the transfer of money from a customer's account to the tax and loan account in\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [859, 243, 1590, 420], \"page_id\": 28}], \"content\": \"the same bank. On occasions, to the extent authorized by the Treasury, banks are permitted to deposit in these accounts proceeds from subscriptions to public debt securities entered for their own account as well as for the account of their customers.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [863, 430, 1595, 653], \"page_id\": 28}], \"content\": \"The tax and loan account system permits the Treasury to leave funds in banks and in the communities in which they arise until such time as the Treasury needs the funds for its operations. In this way the Treasury is able to neutralize the effect of its fluctuating operations on bank reserves and the economy.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [863, 658, 1597, 760], \"page_id\": 28}], \"content\": \"A detailed description of the Treasury's depositary system may be found in the Annual Report of the Secretary of the Treasury for 1955, pages 275-284.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [359, 886, 1287, 918], \"page_id\": 28}], \"content\": \"Table TUS-1. - Status of the Account of the Treasurer of the United States\", \"description\": null, \"id\": 10, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [696, 940, 930, 967], \"page_id\": 28}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 11, \"type\": 